descriptions = {
    'login': 'Sign in with an active staff account. Five failed attempts are free; failure six locks the email for five minutes, seven for ten minutes, and eight or later for 24 hours (a 24-hour lock on a staff account notifies active Admins with sign_in_locked). Successful login or a quiet day resets the counter. OTP configuration off/bound/all may return a challenge instead of a token.',
    'verifyOtp': 'Complete a pending ten-minute sign-in challenge with the six-digit emailed code. Codes are single use, allow five incorrect tries and contribute to the email lockout. Expired challenges return 410.',
    'resendOtp': 'Resend after a 60-second cooldown, replace the previous code and renew its ten-minute expiry. Mail failure returns 502.',
    'changePassword': 'Verify the current password and change it. Revoke other sessions while retaining the current session.',
    'unlock': 'Admin clears the email failure counter, lock and pending sign-in challenges.',
    'assign': 'Assign to an active Support Agent. A Support Agent can claim only their own or unassigned ticket; Admin can assign any active Support Agent.',
    'status': 'Validate the ticket state machine: open → in_progress → waiting_on_customer ↔ in_progress → resolved → closed; resolved/closed → reopened → in_progress. Resolution time pauses while waiting.',
    'integrationShow': 'Return the ticket belonging to this client source system, with only public messages and public attachment metadata. Internal notes and staff audit history are excluded.',
    'csat': 'Record a score from 1 to 5 with an optional comment only after the ticket is resolved or closed.',
    'publicArticle': 'Return a published knowledge article by slug. Draft content is unavailable to integrations.',
    'approve': 'Requires approve refunds; Admin has full authorization and may approve their own request, while other reviewers must differ from the requester. Lock the payment, recheck captured balance, run the gateway, append balanced ledger and commission reversals, and notify the requester. A refund linked to a ticket adds an internal note with the outcome (completed or failed) and notifies the ticket assignee.',
    'reject': 'Requires approve refunds, a rejection reason, and requested status. Admin may reject their own request; other reviewers must differ from the requester. Notifies the requester; a refund linked to a ticket adds an internal note with the reason and notifies the ticket assignee.',
    'simulate': 'Admin-only deterministic sandbox event. Real providers and COD cannot use this endpoint.',
    'capture': 'Capture a valid authorized payment; reject blocked risk, incompatible state, invalid amount or another captured attempt for the same order.',
    'cod': 'Capture COD only after all COD shipments are delivered with proof and cash collected exactly equals the payment amount, and only once the risk review is clear (422 otherwise). Delivery itself never waits for this: a held or mismatched COD payment alerts Finance instead.',
    'clear': 'Clear and capture. Requires edit payments; pending or authorized only (422 otherwise). Sets risk to none, then captures an authorized non-COD payment at once unless its order is cancelled, with ledger and commissions. A COD payment is captured when all its COD shipments are delivered with cash collected. A gateway capture failure returns 200 with status failed and failure_reason.',
    'block': 'Block and cancel. Requires edit payments; pending or authorized only (422 otherwise). Sets risk to blocked and cancels a non-COD payment at the gateway (payment.cancelled webhook to the owning client). A gateway refusal returns 422 and leaves the risk unchanged. COD stays pending and blocked.',
    'proof': 'Store a JPG, PNG or WEBP proof photo up to 4 MB and recipient name. Delivery and COD collection follow the shipment and payment state rules.',
    'import': 'Admin imports the official PSA PSGC CSV, preserving ten-digit codes and upserting by code. Requires code,name,level (official publication aliases are accepted); optional region_code,province_code,city_code.',
    'changePlan': 'Upgrade immediately with half-up prorated integer centavos; a downgrade is scheduled for the next renewal. The server enforces valid active/trialing state.',
    'generate': 'Generate draft settlements for the completed date period. Repeating the same seller and period is idempotent; unsettled commission rows are linked to that settlement. Each new draft notifies Finance (settlement_ready). Scheduled generation instead covers only sellers with unsettled sales and sends one settlement_ready digest per run.',
    'finalize': 'Requires finalize settlements. Freeze a valid draft settlement and append the corresponding ledger postings.',
    'pay': 'Requires pay settlements. Record a confirmed payout of a finalized positive seller balance and append balanced ledger postings. method defaults to the stored seller destination (bank account: bank_transfer, wallet number: gcash) and destination_masked to its masked form; with neither stored, the request returns 422. A repeated call returns 422 and posts nothing.',
    'voidSettlement': 'Void a draft settlement; finalized or paid settlements cannot be voided.',
    'charge': 'Charge an open invoice through the built-in sandbox gateway; successful charge posts the ledger and activates or renews the subscription. A paid invoice returns 200 unchanged. Returns 422 when the subscription is cancelled or expired. A result still pending at the gateway leaves the invoice open without a dunning step and retries after 31 minutes.',
    'run': 'Run idempotent due payment expiry, SLA checks, automatic ticket closure, subscription renewal/dunning, settlement generation, webhook retries and pruning. A database lock serializes runs. When SFA_SCHEDULER_ENABLED=false the secret is still checked and the response is ran: false with paused: true.',
    'test': 'Send an immediate webhook.test event and retain the delivery attempt metadata.',
    'resend': 'Requeue and send the same recorded event ID; the receiver must deduplicate already-processed events.',
}
# Descriptions that depend on the controller, for method names other controllers also use.
controller_descriptions = {
    ('PaymentController', 'options'): 'Requires view payments. Captured payments and orders this user may refund (up to 100 each), plus refund_auto_approve_cap_amount (0 = every refund waits for an approver), refund_auto_approve_daily_limit and refund_auto_approve_reasons for the refund form.',
    ('RefundController', 'store'): 'Requires create refunds and a payment this user may view; Support Agents must link a ticket of that payment. Reserves the amount (captured less refunded less requested, approved or processing refunds) under a payment lock. With refund_auto_approve_cap_amount above 0, a refund within the cap, with a listed reason, on a payment with no earlier automatic approval and within the requester\'s refund_auto_approve_daily_limit is approved and refunded at once (status completed or failed, approved_by null); otherwise it is requested and approvers are notified. Send JSON, or multipart/form-data with the same fields plus up to 3 photos[] (PNG, JPG or WEBP, 4 MB or smaller each); the photos are checked before anything is created (422 on photos or photos.N) and stored with the refund in the same transaction.',
    ('RefundController', 'photo'): "Requires view payments and access to the refund's payment, as GET /refunds/{refund}. Shows one photo the refund check may look at: one added to the refund request, or one in the conversation of a ticket linked to the refund, its payment or that payment's order (the newest 10). Any other attachment id returns 404, so a Finance user sees only the photos behind this refund. Served inline with its image content type.",
    ('RiskReviewController', 'index'):'Requires edit payments. Open risk reviews only: pending or authorized payments whose risk is review or blocked. Captured, cancelled and expired payments leave the queue.',
    ('WebhookDeliveryController', 'resendFailed'): 'Requires manage integrations. Give up to 500 failed deliveries on enabled endpoints of active clients (only this endpoint when endpoint_id is sent) a fresh retry cycle. They are only queued; scheduled work sends them within minutes. A second call queues 0. A disabled endpoint_id returns 422: enable it first.',
    ('BillingController', 'options'): 'Requires view subscriptions. Sellers (with masked payout destinations), plans and categories for billing forms, plus settlement_auto_finalize_days (0 = drafts are never finalized automatically) and current_subscription_seller_ids (sellers that already have a trialing, active or past-due subscription and cannot start another).',
    ('BillingController', 'cancel'): 'Cancel at the period end (default) or immediately. An immediate cancel closes the open invoices: uncollectible when the subscription was past due, otherwise void; an invoice whose payment is pending, authorized or captured is left open.',
    ('AutomationController', 'index'):'Requires manage settings. Scheduler status: whether scheduled work is enabled (SFA_SCHEDULER_ENABLED), whether a run holds the lock now, and the time and counts of the last completed run.',
    ('AutomationController', 'run'): 'Requires manage settings; at most 6 requests a minute. Run the due scheduled work now under the same database lock as the cron (ran: false while another run holds it). Returns 422 while scheduled work is paused. A failed job notifies active Admins once per job per day.',
    ('LogisticsController', 'awaitingBooking'): "Requires create shipments. Order and seller pairs still waiting for a shipment: the order is not cancelled, has a captured or partially refunded payment or a pending COD payment not held for risk review, and the seller has no shipment for it yet. Each row suggests the origin (the seller's active pickup point, else the first active hub), the COD amount (the pending COD total for a single-seller order, 0 when prepaid, null when it must be split) and the customer's last delivery address. Search matches the order, seller or customer. summary.awaiting_booking counts the matching pairs.",
    ('LogisticsController', 'event'): 'Requires edit shipments. Append a status event under the shipment state machine (422 for an invalid move). Picked up requires a tracking number. Returned to sender or cancelled cancels the pending COD payment once no COD parcel of the order can still be delivered and every seller has a shipment; for a prepaid order it notifies users who edit payments (parcel_returned).',
    ('CourierWebhookController', '__invoke'): 'Signed courier status update (X-SFA-Signature, five-minute tolerance), matched by courier and tracking number; a repeated event id returns duplicate: true. With logistics_courier_fill_gaps on, skipped forward steps are recorded first as inferred events (delivered is never inferred). With logistics_courier_pod on, a delivered event with recipient_name and proof_photo records the proof and delivers a prepaid out-for-delivery shipment; a COD shipment, the setting off, or a photo that is not valid base64 PNG/JPG/WEBP up to 2 MB returns 422. A refused event returns 422 and notifies users who edit shipments once per event id (courier_event_rejected).',
    ('MirrorController', 'order'): "Upsert an order of the client's source system with its items; totals are re-checked in integer centavos. Changing status_snapshot to cancelled follows POST /integrations/orders/{id}/cancel: its pending or ready-for-pickup shipments and its pending or authorized payments are cancelled, and it returns 422 (order unchanged) when money was captured or a shipment is already with the courier or delivered. A cancelled order stays cancelled: any other status_snapshot returns 422.",
    ('MirrorController', 'cancel'): "Cancel an order of the client's source system: its pending or ready-for-pickup shipments are cancelled (shipment.status_changed), then its pending or authorized payments. Returns 422 when money was captured (refund instead) or a shipment is already with the courier or delivered; nothing changes then.",
    ('AnalyticsController', 'dashboard'): 'Requires view dashboard. Month-to-date KPIs and distributions for the modules this user may open, recent activity for audit-log readers, and "Needs attention" counts gated by each target list\'s permission (ticket counts follow ticket visibility). Holders of manage settings also get scheduler health.',
    ('SimulatorController', 'index'): 'Admin-only Integration Simulator (off in production unless SFA_SIMULATOR=true). Pickers for the simulated systems: the demo-storefront customers, sellers, categories, orders (items in the PUT /integrations/orders shape), payments, refunds, tickets and shipments by external id or reference (newest 50 each), the PSGC cities a shipping quote can be asked between (quote_cities), the sellers of every storefront for the finance system (newest 100), and the first active courier with the shipments it has not finished. Order, payment, ticket and courier shipment rows carry actions (what SFA would accept for the record now, from the services\' own rules) and next_step (what to do in SFA first when there is no action).',
    ('SimulatorController', 'connect'): 'Admin-only Integration Simulator (404 unless SFA_SIMULATOR=true). Ensures the active clients demo-storefront and demo-finance-gl (read-only, reads_all_financials on), replaces each one\'s token named simulator with a new one carrying the seeded scopes and expiring in 12 hours, (re)activates the demo-storefront webhook endpoint at SFA_PARTNER_URL/webhooks for every event (an existing secret is kept), and gives the first active courier a signing secret when it has none. When the receiver answers, the endpoint\'s deliveries waiting on a retry become due and its failed ones are queued again; the first 20 are sent right after the response. Returns the plain tokens, the courier secret and the sandbox gateway secret (SFA_SANDBOX_WEBHOOK_SECRET, null when unset) so the Admin browser can call the real integration API and sign courier and gateway webhooks; these secrets reach the browser only in simulator mode and are never written to the audit log. The storefront configuration is also pushed to the partner receiver (POST {partner_url}/api/setup, signed with X-SFA-Setup-Signature: sha256=HMAC-SHA256(exact JSON body, APP_KEY), 10-second timeout, best effort); receiver.online reports whether it answered.',
    ('BillingIntegrationController', 'subscriptions'): "Subscriptions of a seller of this client's source system. A client allowed to read every storefront's financials (reads_all_financials) may read any storefront's seller, and must send source_system when the external ID exists in more than one storefront (422 otherwise).",
    ('BillingIntegrationController', 'statements'): "Finalized and paid settlements of a seller of this client's source system. A client allowed to read every storefront's financials (reads_all_financials) may read any storefront's seller, and must send source_system when the external ID exists in more than one storefront (422 otherwise).",
    ('AnalyticsController', 'integration'): "KPI summary for the date range over this client's source system, or over every storefront for a client allowed to read every storefront's financials (reads_all_financials).",
    ('SimulatorController', 'ticketReply'): 'Admin-only simulator: add a public reply from the ticket requester, as the storefront would deliver it. A reply on a waiting ticket moves it back to in progress and notifies the assignee.',
    ('RiskReviewController', 'aiReview'): 'Requires edit payments and access to the payment. The open risk review (pending or authorized, risk review or blocked) is checked for the payment risk signals RSK-1..RSK-5, see GET /ai/rules (a failed check means the signal was found): SFA looks for RSK-1 to RSK-4 in its records and Google Gemini judges RSK-5 and explains why the payment was held. The recommendation follows the checks, not the model: clear when no signal is found, block when a major (required) signal is found, otherwise need_more_info. GET returns the stored answer for the same facts or asks once; POST asks again. Nothing is cleared, blocked or captured, and no audit row is written (the answer is kept in ai_insights). Customer names and contact details are never sent. 422 when the payment is not waiting for a risk decision or ai_enabled/ai_finance_review is off, no key is set or the daily limit is reached; 503 when Gemini is busy, times out, declines or answers in an unusable form.',
    ('RefundController', 'aiReview'): 'Requires approve refunds and access to the payment. The requested refund is checked against the refund rulebook REF-1..REF-9, see GET /ai/rules; the recommendation follows the rule results, not the model. SFA checks REF-1 to REF-5 from the payment, order, deliveries and earlier refunds of the customer (REF-3 counts calendar days in the business timezone); Google Gemini judges REF-6 to REF-9 from the notes, the masked support conversation, the order items with their prices and up to 4 photos (those added to the refund request, then those in the conversation of its tickets), and explains. photos lists the photos it was shown; a new or different photo always asks again. approve when every rule passes, reject when a required rule fails (with a rejection note draft citing the failed rules), otherwise need_more_info. GET returns the stored answer for the same facts or asks once; POST asks again. The refund is never approved or rejected here. 422 when the refund is not requested or the feature is off; 503 when Gemini fails.',
    ('LogisticsController', 'parseAddress'): 'Requires create or edit shipments (or warehouses). Google Gemini splits a pasted Philippine address into parts and SFA matches region, province, city and barangay to its own location tables, so every id comes from SFA (the city first; towns that share a name need the province). Nothing is saved; the form is filled for the person to check. A phone number is read by SFA and masked before anything is sent. checks reports the address rulebook ADR-1..ADR-4 (see GET /ai/rules). 422 when the text is missing or ai_enabled/ai_address_fill is off, no key is set or the daily limit is reached; 503 when Gemini fails. Limited to 20 requests a minute per user.',
    ('AnalyticsController', 'ask'): 'Requires view analytics. Google Gemini answers a question by calling SFA read-only report functions (the same summary and reports as GET /analytics, with the caller permissions and validated filters), at most 4 rounds; it never queries the database. Emails, phone numbers and long numbers in the question are masked. Each question is kept in ai_insights instead of the audit log. checks reports the reporting rulebook ASK-1..ASK-3 (see GET /ai/rules). 422 when the question is missing or ai_enabled/ai_ask_data is off, no key is set or the daily limit is reached; 503 when Gemini fails or does not finish. Limited to 10 requests a minute per user.',
    ('TicketController', 'aiDraft'): 'Requires edit tickets and access to the ticket (a Support Agent: their own or unassigned tickets). Asks Google Gemini for a reply draft built from the published knowledge base, shared canned responses, the last 10 public messages (emails, phone numbers and long numbers masked) and the linked order, payment and shipment the caller may view. SFA checks the draft against the reply guidelines RPL-1..RPL-5 and Gemini judges RPL-6 and RPL-7 (see GET /ai/rules); needs_correction is true when a required rule fails. Nothing is sent or changed; the answer is stored in ai_insights and the same input returns the stored draft unless fresh is true. 422 when ai_enabled or ai_reply_drafts is off, no key is set, the daily token limit is reached, or the ticket is closed; 503 when Gemini is busy, times out, declines or answers in an unusable form. Limited to 20 requests a minute per user.',
    ('TicketController', 'message'): 'Requires edit tickets. Add a public reply or an internal note. A public reply sets the first response, moves an open or reopened ticket to in progress, and assigns an unassigned ticket to the replying Support Agent. The optional status (waiting_on_customer or resolved) is applied in the same transaction.',
    ('TicketController', 'integrationMessage'): 'Add a public reply from the requester. A reply on a waiting_on_customer ticket moves it back to in_progress, resuming the resolution clock, and notifies the assignee.',
    ('TicketController', 'store'): 'Open a ticket (staff need create tickets). When no payment or shipment is given, the order\'s only payment is linked to a payment or refund_return ticket, and its only shipment (for a seller requester, that seller\'s only shipment) to a delivery or refund_return ticket. With ticket_auto_acknowledge on, a public automatic reply with the first-response target is added and sent to the owning client as ticket.replied; it does not count as the first response.',
    ('TicketController', 'csat'):'Record the requester satisfaction score (1 to 5) after the ticket is resolved or closed. When the score first drops to 2 or below, the active Admins and the assignee are notified (ticket_low_csat); a repeated low score does not notify again.',
    ('UserController', 'update'): 'Admin only. Update a staff account. Deactivating it, or removing both its Admin and Support Agent roles, returns its open tickets to the unassigned queue; the audit row records released_tickets.',
    ('SimulatorController', 'ticketRating'): 'Admin-only simulator: record the requester satisfaction score (1 to 5) and comment after the ticket is resolved or closed.',
    ('SimulatorController', 'runScheduled'): 'Admin-only simulator: run the scheduled work now (renewals and dunning, settlement generation, SLA alerts, automatic closure, webhook retries) under the same database lock.',
    ('SimulatorController', 'simrxSetup'): 'Built-in stand-in for the partner receiver on hosted demos (404 unless the simulator is enabled): stores the connection payload POSTed by the simulator connect handshake so webhooks can be signature-checked. Only this SFA can call it: X-SFA-Setup-Signature must be sha256= followed by the hex HMAC-SHA256 of the exact raw body keyed with APP_KEY, or it answers 401 before validating or storing anything. Point SFA_PARTNER_URL at {app}/api/v1/simrx to use it instead of tools/partner-simulator.',
    ('SimulatorController', 'simrxWebhook'): 'Built-in stand-in for the partner receiver (404 unless the simulator is enabled): verifies X-SFA-Signature (t,v1 HMAC, five-minute tolerance) against the secret stored by POST /simrx/api/setup and keeps the last 30 events for GET /simulator/simrx. 409 when connect has not run yet.',
    ('SimulatorController', 'simrxIndex'): 'Admin-only simulator: whether the built-in receiver has been set up and its last 30 received events (newest first; each has at, event, delivery and the signed payload). The only way to read them.',
    ('SimulatorController', 'simrxPage'): 'Public address of the built-in partner receiver (404 unless the simulator is enabled): a short HTML page saying what the address is for. It shows no received events, payloads, counts or settings (staff read them with GET /simulator/simrx), and is sent with X-Robots-Tag: noindex and Cache-Control: no-store.',
    ('SimulatorController', 'settlementFile'): 'Admin-only simulator: download a sample gateway settlement CSV (date, gateway_reference, amount, fee) for the period, built from the captured gateway payments (cash on delivery is left out) with one short amount (PHP 1.00 short, or half short for a capture under PHP 2.00, so it stays positive), one omitted payment and one unknown reference so every reconciliation outcome appears. A payment an earlier import already listed as missing is included again, so importing a later file for an overlapping period resolves that row automatically.',
    ('ReconciliationController', 'store'): 'Requires edit payments. Import a gateway settlement CSV and match each row to a payment (matched, amount_mismatch, missing_in_sfa), then add missing_in_report rows for payments the gateway captured in the period (never cash on delivery; subscription charges included) that the file omits. An earlier unresolved missing_in_report row whose payment this file reports with matching amounts is resolved automatically (resolved_by null, an explanatory note, and an audit row with automation reconciliation_auto_resolve); an amount mismatch never resolves one.',
    ('AiRulesController', '__invoke'): "Any signed-in staff member (no extra permission; integration tokens get 403). The rulebooks every AI feature checks, in order (refund, risk, reply, triage, address, delivery, ask): each rule's id, kind (sfa: checked by SFA's own code; ai: judged by Google Gemini), severity (required or advisory) and description with the current settings filled in, plus the failed-delivery playbook. Nothing is sent to Gemini.",
    ('ReconciliationController', 'resolve'): 'Requires edit payments. Resolve one unmatched item with a note. The item is locked and re-checked, so a matched or already resolved item (including one resolved automatically) returns 422.',
}

paths = {}
for route in ROUTES:
    if not route['uri'].startswith('api/v1/'): continue
    path = '/' + route['uri']
    relative = path.removeprefix('/api/v1/')
    action = route['action'].split('\\')[-1]
    controller, method_name = (action.split('@', 1) + ['__invoke'])[:2] if '@' in action else (action, '__invoke')
    integration = relative.startswith('integrations/')
    public = relative in ['health', 'openapi.yaml', 'login', 'login/otp', 'login/otp/resend', 'simrx']
    inbound = relative.startswith('webhooks/') or relative.startswith('simrx/')
    cron = relative == 'cron/run'
    middleware = route.get('middleware', [])
    scopes = [value.split('CheckAbilities:', 1)[1] for value in middleware if 'CheckAbilities:' in value]
    tag = 'Integrations' if integration else ('Webhooks inbound' if inbound else ('Authentication' if controller == 'AuthController' else 'Customer support' if controller in ['TicketController', 'KnowledgeController'] else 'Payments & transactions' if controller in ['PaymentController', 'RefundController', 'LedgerController', 'ReconciliationController', 'RiskReviewController'] else 'Logistics & locations' if controller in ['LogisticsController', 'LogisticsConfigController', 'LocationController'] else 'Subscriptions & commissions' if controller == 'BillingController' else 'Analytics & reports' if controller == 'AnalyticsController' else 'Administration'))
    for verb in route['method'].split('|'):
        if verb == 'HEAD': continue
        operation = {'operationId': re.sub(r'[^a-zA-Z0-9]+', '_', verb.lower() + '_' + relative).strip('_'), 'tags': [tag], 'summary': f'{verb} /{relative}', 'description': controller_descriptions.get((controller, method_name)) or descriptions.get(method_name, f'{verb.title()} the {relative.replace("/", " ").replace("-", " ")} resource. All writes are validated and authorized on the server; reads include only records permitted to this identity.'), 'parameters': [], 'responses': {code: {'$ref': '#/components/responses/' + name} for code, name in [('401', 'Unauthenticated'), ('403', 'Forbidden'), ('404', 'NotFound'), ('422', 'ValidationError'), ('429', 'RateLimited')]}}
        operation['security'] = [] if public else [{'WebhookSignature': []}] if inbound else [{'CronBearer': []}] if cron else [{'IntegrationBearer': []}] if integration else [{'StaffBearer': []}]
        if scopes: operation['x-required-scopes'] = scopes
        if not (public or inbound or integration or cron): operation['x-authorization'] = 'Active staff session with the module permission and role visibility rules; Admin-only user and integration administration.'
        for parameter in re.findall(r'\{([^}]+)\}', path):
            schema = enum(['couriers', 'zones', 'rates', 'warehouses']) if parameter == 'kind' else string(format='uuid') if parameter == 'delivery' else enum(['sandbox', 'cod']) if parameter == 'gateway' else string(maxLength=255) if parameter in ['reference', 'external_id', 'externalId', 'slug', 'courierCode'] else ID
            operation['parameters'].append({'name': parameter, 'in': 'path', 'required': True, 'schema': schema})
        is_list = verb == 'GET' and (relative in list_models or relative.startswith('locations/') or (integration and relative.endswith('/statements')))
        if is_list:
            operation['parameters'] += [query_param(*entry) for entry in query_base]
            operation['parameters'] += [query_param('date_from', DATE, 'Inclusive date in the business timezone.'), query_param('date_to', DATE, 'Inclusive end date in the business timezone; must be on or after date_from.')]
            model = list_models.get(relative, 'Settlement' if relative.endswith('/statements') else 'Location')
            success_schema = ref(model + 'Page')
        else:
            success_schema = ref('Message') if verb == 'DELETE' else {'type': 'object', 'additionalProperties': True}
        if relative == 'users' and verb == 'GET': operation['parameters'] += [query_param('role', string()), query_param('status', enum(['active', 'inactive', 'locked']))]
        if relative == 'audit-logs' and verb == 'GET': operation['parameters'] += [query_param('user_id', ID), query_param('action', string()), query_param('entity_type', string())]
        if relative == 'notifications' and verb == 'GET': operation['parameters'].append(query_param('is_read', BOOL))
        if relative in ['payments', 'refunds', 'risk-reviews', 'ledger', 'logistics/shipments', 'subscriptions', 'invoices', 'commissions', 'settlements', 'payouts'] and verb == 'GET':
            filters = {'payments': ['status', 'method', 'risk_level', 'customer_id', 'order_id'], 'refunds': ['status', 'payment_id'], 'risk-reviews': ['risk_level'], 'ledger': ['entry_type', 'account'], 'logistics/shipments': ['status', 'courier_id', 'seller_id'], 'subscriptions': ['status', 'seller_id', 'plan_id'], 'invoices': ['status', 'seller_id', 'subscription_id'], 'commissions': ['seller_id', 'payment_id'], 'settlements': ['status', 'seller_id'], 'payouts': ['status']}[relative]
            operation['parameters'] += [query_param(name, ID if name.endswith('_id') else string()) for name in filters]
        if relative == 'logistics/shipments' and verb == 'GET': operation['parameters'].append(query_param('overdue', BOOL, 'Only shipments still on their way after the last promised day in the business timezone (returning parcels are not late). summary.overdue counts them for the other filters.'))
        if relative == 'support/tickets' and verb == 'GET': operation['parameters'] += [query_param('status', enum(TICKET_STATUS)), query_param('priority', enum(PRIORITIES)), query_param('category', enum(TICKET_CATEGORIES)), query_param('channel', enum(CHANNELS + ['system'])), query_param('assignee', string(description='me, unassigned, or an active agent ID')), query_param('sla_state', enum(['on_track', 'at_risk', 'breached', 'met']))]
        if relative == 'support/kb/articles' and verb == 'GET': operation['parameters'] += [query_param('category_id', ID), query_param('status', enum(['draft', 'published']))]
        if relative == 'integrations/kb/articles' and verb == 'GET': operation['parameters'].append(query_param('category_id', ID))
        if relative == 'support/canned-responses' and verb == 'GET': operation['parameters'].append(query_param('is_shared', BOOL))
        if relative == 'integration-clients' and verb == 'GET': operation['parameters'].append(query_param('is_active', BOOL))
        if relative.endswith('webhook-endpoints') and verb == 'GET': operation['parameters'] += [query_param('is_active', BOOL), query_param('client_id', ID)] if not integration else [query_param('is_active', BOOL)]
        if relative == 'webhook-deliveries' and verb == 'GET': operation['parameters'] += [query_param('endpoint_id', ID), query_param('status', enum(['pending', 'processing', 'delivered', 'failed'])), query_param('event_type', enum(EVENTS + ['webhook.test']))]
        if relative.startswith('locations/') and verb == 'GET': operation['parameters'] += [query_param(name, ID) for name in ['region_id', 'province_id', 'city_id']]
        if controller == 'AnalyticsController' and method_name != 'ask': operation['parameters'] += [query_param('date_from', DATE), query_param('date_to', DATE), query_param('seller_id', ID), query_param('method', enum(METHODS)), query_param('courier_id', ID)]
        if relative == 'analytics/export': operation['parameters'].append(query_param('report', enum(['all', 'revenue_by_day', 'payments_by_method', 'refunds_by_reason', 'tickets_by_category', 'ticket_status', 'shipment_status', 'on_time_by_courier', 'top_sellers', 'mrr_by_plan']), required=True))
        if relative == 'integrations/subscriptions': operation['parameters'].append(query_param('seller', string(maxLength=255), "Seller external ID (in this client's source system unless it reads every storefront's financials).", True))
        if relative in ['integrations/subscriptions', 'integrations/sellers/{externalId}/statements']: operation['parameters'].append(query_param('source_system', string(maxLength=80), "Storefront of the seller. Only a client that reads every storefront's financials can reach another storefront; it must send this when the external ID exists in more than one storefront."))
        if any('Idempotency' in value for value in middleware):
            operation['parameters'].append({'name': 'Idempotency-Key', 'in': 'header', 'required': True, 'description': 'Stable key for this creation request (24-hour retention). Same key and identical request replay the saved response; a changed request returns 422. Concurrent in-flight work may return 409.', 'schema': string(minLength=1, maxLength=255)})
            operation['responses']['409'] = {'description': 'A request with this key is still being processed. Retry the same request.', 'content': json_content(ref('Error'))}
        request_name = request_map.get((controller, method_name))
        if request_name and verb in ['POST', 'PUT', 'PATCH']: operation['requestBody'] = body(request_name)
        if controller == 'TicketController':
            if method_name == 'store': operation['requestBody'] = body('IntegrationTicketInput' if integration else 'TicketInput'); success_schema = ref('Ticket')
            if method_name == 'update': operation['requestBody'] = body('TicketUpdate'); success_schema = ref('Ticket')
            if method_name in ['show', 'integrationShow', 'assign', 'status', 'csat']: success_schema = ref('Ticket')
            if method_name == 'assign': operation['requestBody'] = inline_body(obj({'assignee_id': {'oneOf': [ID, string(const='me')]}}, ['assignee_id']))
            if method_name == 'status': operation['requestBody'] = inline_body(obj({'status': enum(TICKET_STATUS), 'note': nullable(string(maxLength=2000))}, ['status']))
            if method_name == 'csat': operation['requestBody'] = inline_body(obj({'score': integer(minimum=1, maximum=5), 'comment': nullable(string(maxLength=2000))}, ['score']))
            if method_name in ['message', 'integrationMessage']:
                name = 'IntegrationTicketMessageInput' if integration else 'TicketMessageInput'; operation['requestBody'] = upload(name); operation['requestBody']['content'].update(json_content(ref(name))); success_schema = ref('TicketMessage')
            if method_name == 'aiDraft': operation['requestBody'] = {'required': False, 'content': json_content(obj({'fresh': {**BOOL, 'description': 'Ask Gemini again even when nothing changed.'}}))}; success_schema = ref('AiReplyDraft'); operation['responses']['503'] = AI_UNAVAILABLE
            if method_name == 'messages': success_schema = ref('TicketMessagePage'); operation['parameters'] += [query_param(*entry) for entry in query_base[:2]]
            if method_name == 'options': success_schema = obj({'customers': array(ref('Customer')), 'sellers': array(ref('Seller')), 'orders': array(ref('Order')), 'payments': array(obj({'id': ID, 'reference': string(), 'order_id': nullable(ID), 'status': enum(PAYMENT_STATUS)})), 'shipments': array(ref('Shipment')), 'agents': array(ref('StaffUser'))})
        if controller == 'AuthController': success_schema = {'oneOf': [ref('LoginResult'), ref('OtpChallenge')]} if method_name == 'login' else ref('LoginResult') if method_name == 'verifyOtp' else ref('OtpResendResult') if method_name == 'resendOtp' else ref('StaffUser') if method_name in ['profile', 'updateProfile'] else ref('Message')
        if relative.startswith('login/otp'): operation['responses']['410'] = {'description': 'Sign-in challenge expired, consumed, disabled or exhausted; start again from the password.', 'content': json_content(ref('Error'))}; operation['responses']['502'] = {'description': 'Code email delivery failed; no staff token is issued.', 'content': json_content(ref('Error'))}
        if relative == 'login': operation['responses']['502'] = {'description': 'Code email delivery failed.', 'content': json_content(ref('Error'))}
        if controller == 'UserController' and method_name in ['store', 'update']: success_schema = ref('StaffUser')
        if relative == 'roles': success_schema = array(ref('Role'))
        if relative == 'settings': success_schema = ref('Settings')
        if relative in ['cron/run', 'automation/run', 'simulator/run-scheduled']: success_schema = ref('SchedulerResult')
        if controller == 'SimulatorController' and method_name in ['index', 'connect']: success_schema = ref('SimulatorPickers' if method_name == 'index' else 'SimulatorConnection')
        if relative == 'automation': success_schema = ref('AutomationStatus')
        if controller == 'AiRulesController': success_schema = ref('AiRulebooks')
        if method_name == 'unreadCount': success_schema = obj({'count': integer(minimum=0)}, ['count'])
        if controller == 'NotificationController' and method_name == 'read': success_schema = ref('Notification')
        if controller == 'IntegrationClientController' and method_name in ['store', 'update']: success_schema = ref('IntegrationClient')
        if method_name == 'issueToken': success_schema = ref('TokenResult')
        if controller == 'WebhookEndpointController' and method_name in ['store', 'update']: operation['requestBody'] = body('IntegrationWebhookEndpointInput' if integration else 'WebhookEndpointInput'); success_schema = ref('WebhookEndpointResult')
        if controller == 'WebhookEndpointController' and method_name == 'test': success_schema = ref('WebhookDelivery')
        if controller == 'WebhookDeliveryController' and method_name == 'resend': success_schema = ref('WebhookDelivery')
        if controller == 'WebhookDeliveryController' and method_name == 'resendFailed': operation['requestBody'] = {'required': False, 'content': json_content(obj({'endpoint_id': nullable(ID)}))}; success_schema = obj({'requeued': integer(minimum=0, maximum=500)}, ['requeued'])
